planned!("operation-effect-on" => cantrip_mechanics::effects::effect_on(g, asker, EffectOn::EachSpell(|q: &dyn Query, asker: &Asker, id: ObjectId| (q.chars(id).is(CardType::Creature) && cast_of(q, id).is_some_and(|cast| Some(asker.controller).into_iter().collect::<Vec<PlayerId>>().contains(&cast.player)))), &[SpellEffect::CantBeCountered], Some(Duration::EndOfTurn))?);
